const std = @import("std");
const mem = std.mem;

fn parseLine(allocator: mem.Allocator, line: []const u8) ![]i16 {
    var count: usize = 0;
    var in_token = false;
    for (line, 0..) |c, i| {
        const delim = c == ' ' or c == '\t' or c == '\r';
        if (delim) {
            in_token = false;
        } else if (!in_token) {
            count += 1;
            in_token = true;
        }
    }
    const result = try allocator.alloc(i16, count);
    var result_index: usize = 0;
    var start: ?usize = null;
    for (line, 0..) |c, i| {
        const delim = c == ' ' or c == '\t' or c == '\r';
        if (delim) {
            if (start) |s| {
                const token = line[s..i];
                const val = std.fmt.parseInt(i16, token, 10) catch return error.InvalidCharacter;
                result[result_index] = val;
                result_index += 1;
                start = null;
            }
        } else {
            if (start == null) {
                start = i;
            }
        }
    }
    if (start) |s| {
        const token = line[s..];
        const val = std.fmt.parseInt(i16, token, 10) catch return error.InvalidCharacter;
        result[result_index] = val;
    }
    return result;
}

fn tokenAt(line: []const u8, col_index: usize) ?i16 {
    var current: usize = 0;
    var start: ?usize = null;
    for (line, 0..) |c, i| {
        const delim = c == ' ' or c == '\t' or c == '\r';
        if (delim) {
            if (start) |s| {
                if (current == col_index) {
                    const token = line[s..i];
                    return std.fmt.parseInt(i16, token, 10) catch return null;
                }
                current += 1;
                start = null;
            }
        } else {
            if (start == null) {
                start = i;
            }
        }
    }
    if (start) |s| {
        if (current == col_index) {
            const token = line[s..];
            return std.fmt.parseInt(i16, token, 10) catch return null;
        }
    }
    return null;
}

fn countLines(s: []const u8) usize {
    var count: usize = 0;
    for (s) |c| {
        if (c == '\n') count += 1;
    }
    if (s.len > 0 and s[s.len - 1] != '\n') {
        count += 1;
    }
    return count;
}

/// Returns the selected row of the matrix.
pub fn row(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    const line_index = @as(usize, @intCast(index)) - 1;
    var current_line: usize = 0;
    var line_start: usize = 0;
    for (s, 0..) |c, i| {
        if (c == '\n') {
            if (current_line == line_index) {
                const line = s[line_start..i];
                return parseLine(allocator, line);
            }
            current_line += 1;
            line_start = i + 1;
        }
    }
    if (current_line == line_index) {
        const line = s[line_start..];
        return parseLine(allocator, line);
    }
    return error.InvalidLine;
}

/// Returns the selected column of the matrix.
pub fn column(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    const col_index = @as(usize, @intCast(index)) - 1;
    const line_count = countLines(s);
